    .picker:hover, .picker.dragging { background: #eaf0ff; border-color: var(--blue); }
    .picker:focus-within { outline: 2px solid var(--blue); outline-offset: 3px; }
    .picker input { position: absolute; inset: 0; width: 100%; opacity: 0; cursor: pointer; }
    .picker strong { color: var(--blue); font-size: .93rem; }
    .picker small { color: var(--muted); }
    .filename { margin-top: 10px; color: var(--muted); font-size: .8rem; overflow-wrap: anywhere; }
    .controls { display: grid; gap: 21px; border-top: 1px solid var(--line); margin-top: 23px; padding-top: 21px; }
    .control-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
    .control-head label { font-weight: 650; font-size: .89rem; }
    #quality-value { color: var(--blue); background: #edf1ff; border-radius: 6px; padding: 3px 7px; font-size: .8rem; font-weight: 700; }
    input[type="range"] { width: 100%; margin: 12px 0 2px; accent-color: var(--blue); cursor: pointer; }
    .scale { display: flex; justify-content: space-between; font-size: .73rem; color: var(--muted); }
    .number-field { display: flex; align-items: center; margin-top: 8px; border: 1px solid var(--line); border-radius: 9px; }
    .number-field:focus-within { outline: 2px solid var(--blue); outline-offset: 2px; }
    .number-field input { width: 100%; min-width: 0; background: transparent; border: 0; outline: 0; padding: 10px 12px; color: inherit; font: inherit; }
    .number-field span { padding: 0 12px; color: var(--muted); font-size: .8rem; }
    .hint { color: var(--muted); font-size: .76rem; margin-top: 7px; line-height: 1.45; }
    .preview { padding: 21px; }
    .preview-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 15px; }
    #dimensions { font-size: .8rem; color: var(--muted); font-variant-numeric: tabular-nums; }
    .stage {
      display: grid; place-items: center; height: clamp(260px, 38vw, 420px);
      border: 1px solid #e0e5ef; border-radius: 12px; overflow: hidden;
      background: radial-gradient(#cbd4e7 1px, transparent 1px) 0 0 / 16px 16px, #f2f5fb;
    }
    .empty { display: grid; justify-items: center; gap: 9px; padding: 18px; text-align: center; }
    .empty-icon { display: grid; place-items: center; width: 54px; height: 54px; margin-bottom: 4px; border: 1px solid #d7dff5; border-radius: 14px; background: #fff; color: var(--blue); }
    .empty p { color: var(--muted); font-size: .85rem; }
    .stage img { width: 100%; height: 100%; min-height: 0; object-fit: contain; }
    [hidden] { display: none !important; }
    .results { display: grid; grid-template-columns: 1fr 1fr auto; gap: 12px; align-items: center; margin-top: 16px; }
    .metric { padding: 11px 12px; background: #f4f6fb; border-radius: 9px; min-width: 0; display: grid; gap: 3px; }
    .metric span { color: var(--muted); font-size: .74rem; }
    .metric output { font-size: .96rem; font-weight: 700; font-variant-numeric: tabular-nums; }
    button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; border: 0; border-radius: 9px; padding: 12px 15px; color: white; background: var(--blue); font: inherit; font-size: .85rem; font-weight: 650; cursor: pointer; }
    button:hover:not(:disabled) { background: #1c38b5; }
    button:disabled { background: #e6eafa; color: #59658c; cursor: default; }
    button:focus-visible, input[type="range"]:focus-visible { outline: 2px solid var(--blue); outline-offset: 3px; }
    .status { margin-top: 12px; font-size: .82rem; color: var(--muted); }
    .status:empty { display: none; }
    .status.error { color: #a12433; }
    @media (max-width: 730px) {
      main { margin: 32px auto; width: calc(100% - 28px); }
      .layout { grid-template-columns: 1fr; gap: 14px; }
    }
    @media (max-width: 460px) {
      .settings, .preview { padding: 16px; }
      .results { grid-template-columns: 1fr 1fr; }
      #download { grid-column: 1 / -1; }
    }
  </style>
</head>
<body>
  <main>
    <header>
      <h1>JPEG Studio</h1>
      <p>Resize and compress an image right in your browser.</p>
    </header>

    <div class="layout">
      <section class="card settings" aria-labelledby="settings-title">
        <h2 id="settings-title">Image settings</h2>
        <label class="picker" id="drop-zone">
          <ryugi-icon name="upload" size="21" style="color:var(--blue)" aria-hidden="true"></ryugi-icon>
          <strong>Choose an image</strong>
          <small>or drop a file here</small>
          <input id="image-file" type="file" accept="image/*" aria-label="Choose an image">
        </label>
        <p id="file-name" class="filename" hidden></p>

        <div class="controls">
          <div>
            <div class="control-head">
              <label for="quality">JPEG quality</label>
              <output id="quality-value" for="quality">80%</output>
            </div>
            <input id="quality" type="range" min="1" max="100" value="80">
            <div class="scale"><span>Smaller file</span><span>Higher quality</span></div>
          </div>
          <div>
            <div class="control-head"><label for="max-width">Max width</label></div>
            <div class="number-field">
              <input id="max-width" type="number" min="1" step="1" value="1600" required aria-describedby="width-hint">
              <span aria-hidden="true">px</span>
            </div>
            <p class="hint" id="width-hint">Keeps the original proportions. Smaller images stay at their original width.</p>
          </div>
        </div>
      </section>

      <section class="card preview" aria-labelledby="preview-title">
        <div class="preview-head">
          <h2 id="preview-title">Compressed preview</h2>
          <span id="dimensions"></span>
        </div>
        <div class="stage">
          <div class="empty" id="empty">
            <div class="empty-icon"><ryugi-icon name="image" size="25" aria-hidden="true"></ryugi-icon></div>
            <strong id="empty-title">No image selected</strong>
            <p id="empty-description">Choose a file to see your JPEG preview.</p>
          </div>
          <img id="preview-image" alt="Compressed JPEG preview" hidden>
        </div>
        <div class="results">
          <div class="metric"><span id="original-label">Original size</span><output id="original-size" aria-labelledby="original-label">—</output></div>
          <div class="metric"><span id="compressed-label">JPEG size</span><output id="compressed-size" aria-labelledby="compressed-label">—</output></div>
          <button id="download" type="button" disabled>
            <ryugi-icon name="download" size="16" aria-hidden="true"></ryugi-icon>
            Download JPEG
          </button>
        </div>
        <p class="status" id="status" role="status"></p>
      </section>
    </div>
  </main>

  <script>
    const fileInput = document.getElementById('"'image-file');
    const dropZone = document.getElementById('drop-zone');
    const fileName = document.getElementById('file-name');
    const quality = document.getElementById('quality');
    const qualityValue = document.getElementById('quality-value');
    const maxWidth = document.getElementById('max-width');
    const dimensions = document.getElementById('dimensions');
    const originalSize = document.getElementById('original-size');
    const compressedSize = document.getElementById('compressed-size');
    const previewImage = document.getElementById('preview-image');
    const empty = document.getElementById('empty');
    const emptyTitle = document.getElementById('empty-title');
    const emptyDescription = document.getElementById('empty-description');
    const download = document.getElementById('download');
    const status = document.getElementById('status');

    let selectedFile;
    let sourceImage;
    let selection = 0;
    let revision = 0;
    let pending;
    let resultUrl;

    function formatSize(bytes) {
      const units = ['B', 'KB', 'MB', 'GB', 'TB'];
      let value = bytes;
      let unit = 0;
      while (value >= 1000 && unit < units.length - 1) {
        value /= 1000;
        unit++;
      }
      return new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(value) + ' ' + units[unit];
    }

    function setStatus(message, error = false) {
      status.textContent = message;
      status.classList.toggle('error', error);
    }

    function clearResult(title, description = '') {
      if (resultUrl) URL.revokeObjectURL(resultUrl);
      resultUrl = undefined;
      previewImage.removeAttribute('src');
      previewImage.hidden = true;
      empty.hidden = false;
      emptyTitle.textContent = title;
      emptyDescription.textContent = description;
      emptyDescription.hidden = "'!description;
      compressedSize.textContent = '"'—';
      dimensions.textContent = '';
      download.disabled = true;
    }

    async function compress(currentRevision) {
      const width = Math.min(sourceImage.naturalWidth, maxWidth.valueAsNumber);
      const height = Math.max(1, Math.round(sourceImage.naturalHeight * (width / sourceImage.naturalWidth)));
      const canvas = document.createElement('canvas');
      try {
        canvas.width = width;
        canvas.height = height;
        const context = canvas.getContext('2d', { alpha: false });
        if ("'!context) throw new Error('"'Canvas unavailable');
        context.fillStyle = '#fff';
        context.fillRect(0, 0, width, height);
        context.imageSmoothingQuality = 'high';
        context.drawImage(sourceImage, 0, 0, width, height);
        const jpegQuality = quality.valueAsNumber / 100;
        const jpeg = await new Promise(resolve => canvas.toBlob(resolve, 'image/jpeg', jpegQuality));
        if (currentRevision "'!== revision) return;
        if (!jpeg || jpeg.type !== '"'image/jpeg') throw new Error('JPEG unavailable');

        if (resultUrl) URL.revokeObjectURL(resultUrl);
        resultUrl = URL.createObjectURL(jpeg);
        previewImage.src = resultUrl;
        previewImage.hidden = false;
        empty.hidden = true;
        dimensions.textContent = width + ' × ' + height + ' px';
        compressedSize.textContent = formatSize(jpeg.size);
        download.disabled = false;

        const difference = selectedFile.size - jpeg.size;
        const percentage = selectedFile.size
          ? new Intl.NumberFormat(undefined, { style: 'percent', maximumFractionDigits: 1 })
              .format(Math.abs(difference) / selectedFile.size)
          : '';
        if (difference && percentage) {
          const comparison = difference > 0 ? ' smaller' : ' larger';
          const amount = percentage === '0%' ? 'Less than 0.1%' : percentage;
          setStatus(amount + comparison + ' than the original.');
        } else {
          setStatus('Same file size as the original.');
        }
      } catch {
        if (currentRevision "'!== revision) return;
        clearResult('"'Preview unavailable');
        setStatus('Could not create a JPEG at this size. Try a lower max width.', true);
      } finally {
        canvas.width = 0;
        canvas.height = 0;
      }
    }

    function renderSettings() {
      qualityValue.textContent = quality.value + '%';
      clearTimeout(pending);
      const currentRevision = ++revision;
      if ("'!sourceImage) return;
      if (!maxWidth.validity.valid) {
        clearResult('"'Set a max width', 'Enter a whole number of at least 1 pixel.');
        setStatus('Enter a whole number of at least 1 pixel.', true);
        return;
      }
      if ("'!resultUrl) clearResult('"'Compressing image…');
      download.disabled = true;
      setStatus('Compressing image…');
      pending = setTimeout(() => compress(currentRevision), 120);
    }

    async function chooseFile(file) {
      if ("'!file) return;
      const currentSelection = ++selection;
      ++revision;
      clearTimeout(pending);
      selectedFile = file;
      sourceImage = undefined;
      fileName.textContent = file.name;
      fileName.hidden = false;
      originalSize.textContent = formatSize(file.size);
      clearResult('"'Reading image…');
      setStatus('');

      const sourceUrl = URL.createObjectURL(file);
      const image = new Image();
      try {
        image.src = sourceUrl;
        await image.decode();
        if (currentSelection "'!== selection) return;
        if (!image.naturalWidth || !image.naturalHeight) throw new Error('"'Image has no dimensions');
        sourceImage = image;
        renderSettings();
      } catch {
        if (currentSelection "'!== selection) return;
        clearResult('"'Image could not be opened', 'Choose another image file.');
        setStatus('This file could not be read as an image by your browser.', true);
      } finally {
        URL.revokeObjectURL(sourceUrl);
      }
    }

    fileInput.addEventListener('change', () => chooseFile(fileInput.files[0]));
    dropZone.addEventListener('dragover', event => {
      event.preventDefault();
      event.dataTransfer.dropEffect = 'copy';
      dropZone.classList.add('dragging');
    });
    dropZone.addEventListener('dragleave', () => dropZone.classList.remove('dragging'));
    dropZone.addEventListener('drop', event => {
      event.preventDefault();
      dropZone.classList.remove('dragging');
      const file = event.dataTransfer.files[0];
      if ("'!file) return;
      fileInput.value = '"'';
      chooseFile(file);
    });

    for (const control of [quality, maxWidth]) {
      control.addEventListener('input', renderSettings);
      control.addEventListener('change', renderSettings);
    }

    download.addEventListener('click', () => {
      if ("'!resultUrl) return;
      const link = document.createElement('"'a');
      const baseName = selectedFile.name.replace(/\\.["'^.]+$/, '"'') || 'image';
      link.href = resultUrl;
      link.download = baseName + '-compressed.jpg';
      document.body.append(link);
      link.click();
      link.remove();
    });

    renderSettings();
  </script>
</body>
</html>
EOF"

